document.addEventListener('DOMContentLoaded', function () {
  class V5ScrollProductFeatures2 {
    constructor() {
      this.sectionId = '#v5ScrollProductFeatures2';
      this.v5ScrollProductFeatures2PcTrigger = null;
      this.v5ScrollProductFeatures2MbTrigger = null;

      this.mbScreen2Img = document.querySelector(
        '.v5-scroll-product-features-2 .scroll-img-2'
      );
      this.mbScreen3Img = document.querySelector(
        '.v5-scroll-product-features-2 .scroll-img-3-2'
      );
      this.swiperDom = document.querySelector(
        '.v5-scroll-product-features-2 .swiper'
      );

      this.mbSwiper = null;
      this.mbSwiperData = {
        active: false,  // swiper是否启用
        activeIndex: 0, // swiper 当前active的下标
        scrollDirection: 0, // 滚动方向，1：正向；-1：反向
        scrollProgress: 0, // 滚动进度
        screen2Show: false,
        screen3Show: false
      }

      if (window.innerWidth > 1023) {
        this.pcScrollTimeLine();
      } else {
        this.mbSwiperFunc();
        this.mbScrollTimeLine();
      }
      this.observeFunc();
    }

    observeFunc(){
      const self = this;
      // 橱窗版块的DOM元素 需要持续监听
      const pdpInfoContainer = document.querySelector('.section-v5-main-product') || document.querySelector('.product-info-container');

      // 该组件需要持续监听
      const v5Accordion = document.querySelector('.section-v5-accordion');

      if (pdpInfoContainer || v5Accordion) {
        // 创建防抖函数来限制refresh频率
        const debouncedRefresh = window.throttle(() => {
          if(window.innerWidth < 1024){
            if (self.v5ScrollProductFeatures2MbTrigger && typeof self.v5ScrollProductFeatures2MbTrigger.refresh === 'function') {
              self.v5ScrollProductFeatures2MbTrigger.refresh();
            }
          }else{
            if (self.v5ScrollProductFeatures2PcTrigger && typeof self.v5ScrollProductFeatures2PcTrigger.refresh === 'function') {
              self.v5ScrollProductFeatures2PcTrigger.refresh();
            }
          }
          // 观察到变更后，启动/重置空闲期清理计时器
          // if(pdpInfoContainer){
          //   scheduleIdleCleanup();
          // }
        }, 100); // 100ms内最多执行一次

        // 创建ResizeObserver实例
        const observer = new ResizeObserver((entries) => {
          // 检查是否有实际的尺寸变化
          for (let entry of entries) {
            const { height } = entry.contentRect;
            // 只有当尺寸发生实际变化时才触发刷新
            if (height > 0) {
              debouncedRefresh();
              break;
            }
          }
        });

        // 在一段"空闲期"后自动清理，避免过早地 load 时断开监听
        let resizeIdleTimer = null;
        const scheduleIdleCleanup = () => {
          if (resizeIdleTimer) clearTimeout(resizeIdleTimer);
          resizeIdleTimer = setTimeout(() => {
            // 橱窗稳定，卸载监听
            cleanupObserver();
          }, 120000); // 2min，根据需要调整空闲期时长
        };

        // 开始观察元素尺寸变化
        [pdpInfoContainer, v5Accordion].forEach(element => {
          if (element) {
            observer.observe(element);
          }
        });

        // 断开观察
        const cleanupObserver = () => {
          if (observer) {
            observer.disconnect();
          }
          if (resizeIdleTimer) {
            clearTimeout(resizeIdleTimer);
            resizeIdleTimer = null;
          }
        };

        // 在页面隐藏或离开时清理，避免遗漏 load 之后生成的 DOM
        window.addEventListener('pagehide', cleanupObserver);
        document.addEventListener('visibilitychange', function () {
          if (document.visibilityState === 'hidden') cleanupObserver();
        });

        // 清理保障：当组件卸载时也应该断开观察
        if (window.Shopify && window.Shopify.designMode && this.section) {
          const parentSection = this.section.closest('.shopify-section');
          if (parentSection) {
            parentSection.addEventListener('section:unload', cleanupObserver);
          }
        }
      }
    }

    // PC端滚动动画
    pcScrollTimeLine() {
      if (!window._scrollTriggerRegistered) {
        window.gsap.registerPlugin(window.ScrollTrigger);
        window._scrollTriggerRegistered = true;
      }

      const self = this;
      let topH = '4.1666667vw';
      const productTabsBox = document.querySelector('.product-tabs-box,.section-navigation');
      if (productTabsBox) {
        topH = productTabsBox.offsetHeight + 'px';
      } else {
        const header = document.querySelector('jky-header,header-v5');
        topH = header.offsetHeight + 'px';
      }

      let tl;
      // 储存实例动画已经进行了多长的时间
      const time = tl ? tl.time() : 0;
      if (tl) {
        tl.kill();
      }

      tl = window.gsap.timeline({ paused: true });
      self.v5ScrollProductFeatures2PcTrigger = window.ScrollTrigger.create({
        trigger: this.sectionId,
        pin: true, // 将触发元素固定，在激活时
        start: `top ${topH}`, // 当触发元素的顶部碰到视口顶部时
        end: `bottom 25%`, // 在起始位置滚动 xxx 后结束
        scrub: 2, // 平滑擦洗，需要2秒钟来“赶上”滚动条
        smoothChildTiming: true,
        //markers: true,
        snap:[0,0.3,0.6,0.9,1],
        animation: tl,
      });

      tl.addLabel('start')
        .to('.v5-scroll-product-features-2 .big-title1', {
          y: '27.222222vw',
          ease: 'power3.inOut',
          duration: 0.3,
        })
        .to(
          '.v5-scroll-product-features-2 .scroll-img-1',
          {
            y: '-100%',
            ease: 'power3.inOut',
            visibility: 'visible',
            duration: 0.3,
          },
          '<'
        )
        .addLabel('Screen2')
        .to(
          '.v5-scroll-product-features-2 .scroll-img-2',
          {
            opacity: 1,
            ease: 'power3.inOut',
            duration: 0.3,
          },
          'Screen2'
        )

        .addLabel('Screen3')
        .to(
          '.v5-scroll-product-features-2 .big-title1',
          {
            opacity: 0,
            ease: 'power3.inOut',
            duration: 0.1,
          },
          'Screen3'
        )
        .to(
          '.v5-scroll-product-features-2 .scroll-img-2',
          {
            opacity: 0,
            ease: 'power3.inOut',
            duration: 0.1,
          },
          'Screen3'
        )
        .to(
          '.v5-scroll-product-features-2 .scroll-img-3-1',
          {
            opacity: 1,
            ease: 'power3.in',
            duration: 0.3,
          },
          'Screen3'
        )
        .to(
          '.v5-scroll-product-features-2 .scroll-img-3-2',
          {
            y: '-100%',
            ease: 'power3.inOut',
            duration: 0.3,
          },
          'Screen3'
        )
        .to(
          '.v5-scroll-product-features-2 .big-title3',
          {
            opacity: 1,
            ease: 'power3.inOut',
            duration: 0.3,
          },
          'Screen3'
        )
        .to(
          '.v5-scroll-product-features-2 .big-title3',
          {
            visibility: 'visible',
            ease: 'power3.inOut',
            duration: 0.1,
          },
          '>'
        )
        .addLabel('end');
      tl.time(time);
    }

    // 移动端滚动动画
    mbScrollTimeLine() {
      const self = this;
      if (!window._scrollTriggerRegistered) {
        window.gsap.registerPlugin(window.ScrollTrigger);
        window._scrollTriggerRegistered = true;
      }

      let topH = '4.1666667vw';
      const productTabsBox = document.querySelector('.product-tabs-box,.section-navigation');
      if (productTabsBox) {
        topH = productTabsBox.offsetHeight + 'px';
      } else {
        const header = document.querySelector('jky-header,header-v5');
        topH = header.offsetHeight + 'px';
      }

      let tl;
      // 储存实例动画已经进行了多长的时间
      const time = tl ? tl.time() : 0;
      if (tl) {
        tl.kill();
      }
      tl = window.gsap.timeline({ paused: true });
      self.v5ScrollProductFeatures2MbTrigger = window.ScrollTrigger.create({
        trigger: this.sectionId,
        pin: false,
        start: `top 100px`,
        end: `+=${topH + 100}`,
        scrub: true,
        // markers: true,
        snap:[0,1],
        onUpdate: (curr) => {
          // 对接近 1 的值做钳位，避免浮点误差导致日志显示不到 1
          const progress = curr.progress >= 0.9 ? 1 : parseFloat(curr.progress.toFixed(3));
          self.mbSwiperData.scrollProgress = progress;

          if (progress === 0) {
            self.mbSwiper?.slideTo(0);
            self.mbSwiperData = {
              active: false,  // swiper是否启用
              activeIndex: 0, // swiper 当前active的下标
              scrollDirection: 0, // 滚动方向，1：正向；-1：反向
              scrollProgress: 0, // 滚动进度
              screen2Show: false,
              screen3Show: false
            }
            self.mbScreen2Img.style.visibility = 'hidden';
            self.mbScreen3Img.style.visibility = 'hidden';
            self.mbSwiper?.disable();
          }
          self.mbSwiperData.scrollDirection = curr.direction;

          if (curr.direction === 1) {
            // 正向滚动，等于 1，启用 swiper
            if (progress === 1) {
              self.mbSwiperData.active = true;
              self.mbSwiper?.enable();
              self.mbSwiper?.slideTo(0);
            }
          } else {
            // 反向滚动逻辑保持不变
            if (self.mbSwiperData.activeIndex === 1) {
              self.mbSwiper?.slideTo(0);
            }

            if (progress < 0.4 && self.mbSwiperData.active) {
              self.mbSwiperData.active = false;
              self.mbSwiper?.disable();
            }
          }
        },
        animation: tl,
      });

      tl.addLabel('start')
        .to('.v5-scroll-product-features-2 .big-title1', {
          y: '24.5rem',
          ease: 'power3.inOut',
          duration: 0.3
        })
        .to(
          '.v5-scroll-product-features-2 .scroll-img-1',
          {
            visibility: 'visible',
            y: '-100%',
            ease: 'power3.inOut',
            visibility: 'visible',
            duration: 0.3
          },
          '<'
        )
        .to('.v5-scroll-product-features-2 .scroll-img-2', {
          visibility: 'visible',
          ease: 'power3.inOut',
          duration: 0.3,
          onUpdate:()=>{
            // 如果Screen3已显示，则立即隐藏
            if(self.mbSwiperData.screen3Show){
              document.querySelector('.v5-scroll-product-features-2 .scroll-img-3-2').style.visibility = 'hidden';
              self.mbSwiperData.screen3Show = false
            }
          },
          onComplete:()=>{
            if(!self.mbSwiperData.screen3Show && !self.mbSwiperData.screen2Show){
              self.mbSwiperData.screen2Show = true
            }
            if(self.mbSwiperData.screen3Show){
              self.mbSwiper.slideTo(0);
            }
          }
        })
        .addLabel('end');

      tl.time(time);
    }
    // 移动端Swiper
    mbSwiperFunc() {
      const self = this;
      this.mbSwiper = new window.Swiper('.v5-scroll-product-features-2 .swiper',
        {
          direction: 'horizontal',
          slidesPerView: 1.2,
          spaceBetween: 0,
          mousewheel: false,
          slideToClickedSlide: true,
          observer: true, // 开启观察器
          observeParents: true, // 观察父元素变化
          on: {
            slideChangeTransitionStart: function () {
              // 禁止在滚动时触发swiper轮播
              if(ScrollTrigger.isScrolling() && self.mbSwiperData.scrollDirection === 1){
                this.slideTo(0);
                return
              }
              self.mbSwiperData.activeIndex = this.activeIndex;
              if (this.activeIndex === 0) {
                if (!self.mbSwiperData.screen2Show){
                  self.mbSwiperData.screen2Show = true
                  self.mbScreen2Img.style.visibility = 'visible';
                }
                if(self.mbSwiperData.screen3Show){
                  self.mbSwiperData.screen3Show = false
                  window.gsap.to('.v5-scroll-product-features-2 .scroll-img-3-2',{
                      visibility: 'hidden',
                      opacity: 0,
                      y: '100%',
                      ease: 'power3.inOut',
                      duration: 0.1,
                    }
                  );
                }
              }else {
                self.mbSwiperData.screen2Show = false
                self.mbScreen2Img.style.visibility = 'hidden';

                self.mbSwiperData.screen3Show = true
                  window.gsap.to('.v5-scroll-product-features-2 .scroll-img-3-2',{
                    visibility: 'visible',
                    opacity: 1,
                    y: '-100%',
                    ease: 'power3.inOut',
                    duration: 0.3,
                  }
                );
              }
            }
          }
        })

      this.mbSwiper?.disable();
    }
  }
  new V5ScrollProductFeatures2();
});